arguments.query:
SELECT time,pid,ppid,pname,process_name,command_line,childproc_name,parent_process_name,parent_process_path,parent_command_line,process_guid,parent_process_guid,access,raw_event_type,event_id,event_record_id,source_stream,source_row_id,object
FROM audit_logs
WHERE (
  lower(command_line) LIKE '%discordsetup.exe%' OR lower(parent_command_line) LIKE '%discordsetup.exe%' OR lower(parent_process_name) LIKE '%discordsetup.exe%' OR lower(parent_process_path) LIKE '%discordsetup.exe%' OR lower(process_name) LIKE '%discordsetup.exe%' OR lower(pname) LIKE '%discordsetup.exe%' OR lower(object) LIKE '%discordsetup.exe%' OR lower(childproc_name) LIKE '%discordsetup.exe%'
)
AND (
  lower(command_line) LIKE '%squirreltemp%update.exe%' OR lower(childproc_name) LIKE '%squirreltemp%update.exe%' OR lower(process_name) LIKE '%squirreltemp%update.exe%' OR lower(object) LIKE '%squirreltemp%update.exe%'
)
ORDER BY time, event_record_id
LIMIT 30;

